WITH oracle_1 AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=1), oracle_2 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,highPx/10000.0 AS px,MAX(highPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS extreme FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px>=extreme), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=10) SELECT l.mktcode,l.tgtcode,l.bizdate FROM branch_1 l INNER JOIN branch_2 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate;
